//! Standalone signature verification with `SignedData`: certificates, CRLs
//! and certification requests generated by rcgen, and raw (message,
//! algorithm, signature) triples, for ECDSA P-256/P-384, Ed25519 and RSA
//! PKCS #1 and PSS.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod common;

use browntls_pki::{
    Cert, CertificateDer, Error, SignatureVerificationAlgorithm, SignedData,
    SubjectPublicKeyInfoDer, alg_id, anchor_from_trusted_cert,
};
use common::*;
use rcgen::{
    CertificateRevocationListParams, KeyIdMethod, PublicKeyData as _, RevocationReason,
    RevokedCertParams, SerialNumber,
};

const MSG: &[u8] = b"signed data";

/// A DER element (contents shorter than 64 KiB).
fn tlv(tag: u8, value: &[u8]) -> Vec<u8> {
    let mut out = vec![tag];
    match value.len() {
        n if n < 0x80 => out.push(n as u8),
        n if n < 0x100 => out.extend([0x81, n as u8]),
        n => out.extend([0x82, (n >> 8) as u8, n as u8]),
    }
    out.extend_from_slice(value);
    out
}

/// The contents of a complete `SubjectPublicKeyInfo` `SEQUENCE`.
fn spki_contents(spki: &[u8]) -> &[u8] {
    match spki[1] {
        n if n < 0x80 => &spki[2..],
        0x81 => &spki[3..],
        _ => &spki[4..],
    }
}

fn spki_of(cert: &CertificateDer<'_>) -> SubjectPublicKeyInfoDer<'static> {
    SubjectPublicKeyInfoDer::from(
        Cert::try_from(cert)
            .unwrap()
            .subject_public_key_info()
            .to_vec(),
    )
}

/// A key of a type that no algorithm pairs with `sig_alg`'s signatures.
fn other_type_spki(
    sig_alg: &'static rcgen::SignatureAlgorithm,
) -> SubjectPublicKeyInfoDer<'static> {
    let other = if *sig_alg == rcgen::PKCS_ED25519 {
        &rcgen::PKCS_ECDSA_P256_SHA256
    } else {
        &rcgen::PKCS_ED25519
    };
    SubjectPublicKeyInfoDer::from(key_for(other).subject_public_key_info())
}

/// The algorithms of `ALGS` that do not handle `signature_algorithm`.
fn without(signature_algorithm: &[u8]) -> Vec<&'static dyn SignatureVerificationAlgorithm> {
    ALGS.iter()
        .copied()
        .filter(|a| !a.signature_alg_id().matches_signature(signature_algorithm))
        .collect()
}

/// Verifies `der` with `spki`, then checks that it fails with a key of the
/// same type that did not sign it (when there is one), a key of another
/// type, algorithms without the signature's, a tampered `tbs` and a
/// tampered signature.
fn check_signed(
    der: &[u8],
    spki: &SubjectPublicKeyInfoDer<'_>,
    unrelated_spki: Option<&SubjectPublicKeyInfoDer<'_>>,
    other_type: &SubjectPublicKeyInfoDer<'_>,
) {
    let signed = SignedData::from_der(der).unwrap();
    assert_eq!(signed.verify_signature(ALGS, spki), Ok(()));
    if let Some(unrelated) = unrelated_spki {
        assert_eq!(
            signed.verify_signature(ALGS, unrelated),
            Err(Error::InvalidSignatureForPublicKey)
        );
    }
    assert_eq!(
        signed.verify_signature(ALGS, other_type),
        Err(Error::UnsupportedSignatureAlgorithmForPublicKey)
    );
    assert_eq!(
        signed.verify_signature(&without(signed.algorithm()), spki),
        Err(Error::UnsupportedSignatureAlgorithm)
    );
    assert_eq!(
        signed.verify_signature(&[], spki),
        Err(Error::UnsupportedSignatureAlgorithm)
    );

    // The message is the complete tbs element; flip a byte in its middle.
    let message = signed.message();
    let tbs_start = message.as_ptr() as usize - der.as_ptr() as usize;
    let mut tampered = der.to_vec();
    tampered[tbs_start + message.len() / 2] ^= 0x01;
    assert_eq!(
        SignedData::from_der(&tampered)
            .unwrap()
            .verify_signature(ALGS, spki),
        Err(Error::InvalidSignatureForPublicKey)
    );
    let mut tampered = der.to_vec();
    let last = tampered.len() - 1;
    tampered[last] ^= 0x01;
    assert_eq!(
        SignedData::from_der(&tampered)
            .unwrap()
            .verify_signature(ALGS, spki),
        Err(Error::InvalidSignatureForPublicKey)
    );
}

#[test]
fn certificates_crls_and_requests() {
    for alg in [
        &rcgen::PKCS_ECDSA_P256_SHA256,
        &rcgen::PKCS_ECDSA_P384_SHA384,
        &rcgen::PKCS_ED25519,
        &rcgen::PKCS_RSA_SHA256,
        &rcgen::PKCS_RSA_SHA384,
        &rcgen::PKCS_RSA_SHA512,
    ] {
        let chain = Chain::simple(alg, 1);
        let (ee, int, root) = (
            chain.ee_der(),
            chain.intermediate_ders().remove(0),
            chain.root_der(),
        );
        let (ee_spki, int_spki, root_spki) = (spki_of(&ee), spki_of(&int), spki_of(&root));
        // Every RSA key of the test chains is the same one, so there is no
        // unrelated RSA key to try.
        let distinct = |spki| (!alg.is_rsa()).then_some(spki);
        let other_type = other_type_spki(alg);

        // Signed-data verification agrees with path validation.
        assert_eq!(chain.verify_at(NOW), Ok(()), "{alg:?}");
        check_signed(&ee, &int_spki, distinct(&ee_spki), &other_type);
        check_signed(&int, &root_spki, distinct(&int_spki), &other_type);
        // A trust anchor holds the root's key as SubjectPublicKeyInfo
        // contents, which verify the same way.
        let anchor = anchor_from_trusted_cert(&root).unwrap();
        assert_eq!(
            SignedData::from_der(&int)
                .unwrap()
                .verify_signature(ALGS, &anchor.subject_public_key_info),
            Ok(())
        );
        assert_eq!(
            spki_contents(&root_spki),
            anchor.subject_public_key_info.as_ref()
        );
        // `Cert::signed_data` is the same structure.
        let cert = Cert::try_from(&ee).unwrap();
        let from_cert = cert.signed_data();
        let from_der = SignedData::from_der(&ee).unwrap();
        assert_eq!(from_cert.message(), from_der.message());
        assert_eq!(from_cert.algorithm(), from_der.algorithm());
        assert_eq!(from_cert.signature(), from_der.signature());
        assert_eq!(from_cert.verify_signature(ALGS, &int_spki), Ok(()));

        // A CRL signed by the root.
        let crl = CertificateRevocationListParams {
            this_update: at(1_717_000_000),
            next_update: at(1_718_000_000),
            crl_number: SerialNumber::from(7u64),
            issuing_distribution_point: None,
            revoked_certs: vec![RevokedCertParams {
                serial_number: SerialNumber::from_slice(&[0x7b, 4, 5, 6]),
                revocation_time: at(1_716_000_000),
                reason_code: Some(RevocationReason::Superseded),
                invalidity_date: None,
            }],
            key_identifier_method: KeyIdMethod::Sha256,
        }
        .signed_by(&chain.root)
        .unwrap()
        .der()
        .to_vec();
        check_signed(&crl, &root_spki, distinct(&int_spki), &other_type);

        // A self-signed certification request.
        let key = key_for(alg);
        let csr = ee_params(&["request.example"])
            .serialize_request(&key)
            .unwrap()
            .der()
            .to_vec();
        let csr_spki = SubjectPublicKeyInfoDer::from(key.subject_public_key_info());
        check_signed(&csr, &csr_spki, distinct(&int_spki), &other_type);
    }
}

/// Whether rcgen's algorithm is RSA (whose test key is shared).
trait IsRsa {
    fn is_rsa(&self) -> bool;
}

impl IsRsa for rcgen::SignatureAlgorithm {
    fn is_rsa(&self) -> bool {
        *self == rcgen::PKCS_RSA_SHA256
            || *self == rcgen::PKCS_RSA_SHA384
            || *self == rcgen::PKCS_RSA_SHA512
    }
}

#[test]
fn raw_triples() {
    for (alg, alg_id) in [
        (&rcgen::PKCS_ECDSA_P256_SHA256, alg_id::ECDSA_SHA256),
        (&rcgen::PKCS_ECDSA_P384_SHA384, alg_id::ECDSA_SHA384),
        (&rcgen::PKCS_ED25519, alg_id::ED25519),
        (&rcgen::PKCS_RSA_SHA256, alg_id::RSA_PKCS1_SHA256),
    ] {
        let key = key_for(alg);
        let spki = SubjectPublicKeyInfoDer::from(key.subject_public_key_info());
        let signature = sign(&key, MSG);
        let signed = SignedData::from_parts(MSG, alg_id.as_bytes(), &signature);
        assert_eq!(signed.message(), MSG);
        assert_eq!(signed.verify_signature(ALGS, &spki), Ok(()), "{alg:?}");
        assert_eq!(
            SignedData::from_parts(b"other", alg_id.as_bytes(), &signature)
                .verify_signature(ALGS, &spki),
            Err(Error::InvalidSignatureForPublicKey)
        );
        assert_eq!(
            signed.verify_signature(ALGS, &other_type_spki(alg)),
            Err(Error::UnsupportedSignatureAlgorithmForPublicKey)
        );
        // An unknown algorithm, and the identifier with its outer SEQUENCE
        // (contents are expected).
        assert_eq!(
            SignedData::from_parts(MSG, &[0x06, 0x03, 0x2a, 0x03, 0x04], &signature)
                .verify_signature(ALGS, &spki),
            Err(Error::UnsupportedSignatureAlgorithm)
        );
        assert_eq!(
            SignedData::from_parts(MSG, &tlv(0x30, alg_id.as_bytes()), &signature)
                .verify_signature(ALGS, &spki),
            Err(Error::UnsupportedSignatureAlgorithm)
        );
        // The key may also be given as the SubjectPublicKeyInfo contents,
        // as path validation accepts; anything else is malformed.
        let contents = spki_contents(&spki);
        assert_eq!(signed.verify_signature(ALGS, contents), Ok(()));
        let mut both = spki.to_vec();
        both.extend_from_slice(contents);
        for bad in [&both[..], &spki[..spki.len() - 1], &contents[1..], &[]] {
            assert!(signed.verify_signature(ALGS, bad).is_err());
        }
    }
}

#[test]
fn rsassa_pss_identifiers_match_by_canonical_form() {
    let key = key_for(&rcgen::PKCS_RSA_SHA256);
    let spki = SubjectPublicKeyInfoDer::from(key.subject_public_key_info());
    let signature = rsa_pss_sign(MSG);
    let canonical = SignedData::from_parts(MSG, alg_id::RSA_PSS_SHA256.as_bytes(), &signature);
    assert_eq!(canonical.verify_signature(ALGS, &spki), Ok(()));
    assert_eq!(
        canonical.verify_signature(&without(alg_id::RSA_PSS_SHA256.as_bytes()), &spki),
        Err(Error::UnsupportedSignatureAlgorithm)
    );

    // The same parameters with the hash parameters absent instead of NULL
    // and an explicit trailerField 1 (RFC 4055 §2.1, §3.1).
    const RSASSA_PSS: &[u8] = &[
        0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x0a,
    ];
    const MGF1: &[u8] = &[
        0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x08,
    ];
    let sha256 = tlv(
        0x30,
        &tlv(
            0x06,
            &[0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01],
        ),
    );
    let params = |salt: u8| {
        let mut fields = tlv(0xa0, &sha256);
        let mut mgf = MGF1.to_vec();
        mgf.extend(&sha256);
        fields.extend(tlv(0xa1, &tlv(0x30, &mgf)));
        fields.extend(tlv(0xa2, &tlv(0x02, &[salt])));
        fields.extend(tlv(0xa3, &tlv(0x02, &[1])));
        let mut id = RSASSA_PSS.to_vec();
        id.extend(tlv(0x30, &fields));
        id
    };
    let equivalent = params(32);
    assert_ne!(equivalent, alg_id::RSA_PSS_SHA256.as_bytes());
    assert_eq!(
        SignedData::from_parts(MSG, &equivalent, &signature).verify_signature(ALGS, &spki),
        Ok(())
    );
    // A salt other than the digest length has no canonical form.
    assert_eq!(
        SignedData::from_parts(MSG, &params(20), &signature).verify_signature(ALGS, &spki),
        Err(Error::UnsupportedSignatureAlgorithm)
    );
    // PKCS #1 v1.5 algorithms reject the PSS signature.
    assert_eq!(
        SignedData::from_parts(MSG, alg_id::RSA_PKCS1_SHA256.as_bytes(), &signature)
            .verify_signature(ALGS, &spki),
        Err(Error::InvalidSignatureForPublicKey)
    );
}

#[test]
fn malformed_signed_structures() {
    let chain = Chain::simple(&rcgen::PKCS_ECDSA_P256_SHA256, 0);
    let der = chain.ee_der().to_vec();
    assert!(SignedData::from_der(&der).is_ok());

    for len in 0..der.len() {
        assert!(SignedData::from_der(&der[..len]).is_err(), "{len}");
    }
    let mut trailing = der.clone();
    trailing.push(0);
    assert_eq!(
        SignedData::from_der(&trailing).err(),
        Some(Error::TrailingData)
    );

    // The three elements, re-wrapped.
    let contents = &der[4..];
    assert_eq!(der[1], 0x82, "two-octet length");
    let wrap = |tag: u8, body: &[u8]| tlv(tag, body);
    assert!(SignedData::from_der(&wrap(0x30, contents)).is_ok());
    assert_eq!(
        SignedData::from_der(&wrap(0x31, contents)).err(),
        Some(Error::BadDer)
    );
    // A fourth element.
    let mut extra = contents.to_vec();
    extra.extend([0x05, 0x00]);
    assert_eq!(
        SignedData::from_der(&wrap(0x30, &extra)).err(),
        Some(Error::TrailingData)
    );
    // A non-minimal length.
    let mut long = vec![0x30, 0x83, 0x00, der[2], der[3]];
    long.extend(contents);
    assert_eq!(SignedData::from_der(&long).err(), Some(Error::BadDer));
    // The tbs must be a SEQUENCE.
    let mut not_seq = der.clone();
    not_seq[4] = 0x31;
    assert_eq!(SignedData::from_der(&not_seq).err(), Some(Error::BadDer));
    // A signature BIT STRING with unused bits.
    let signed = SignedData::from_der(&der).unwrap();
    let sig_start = signed.signature().as_ptr() as usize - der.as_ptr() as usize;
    let mut unused = der.clone();
    unused[sig_start - 1] = 1;
    assert_eq!(SignedData::from_der(&unused).err(), Some(Error::BadDer));
    // A malformed key.
    for spki in [&[][..], &[0x30, 0x00], &[0x30, 0x02, 0x30, 0x00]] {
        assert!(
            signed
                .verify_signature(ALGS, &SubjectPublicKeyInfoDer::from(spki))
                .is_err()
        );
    }
    let debug = format!("{signed:?}");
    assert!(debug.starts_with("SignedData { message_len: "), "{debug}");
}
